@using sv_f71603591e574d85a2bc94f983845435.Services

<nav class="nav flex-column nav-pills settings-sidebar" role="tablist">
    @foreach (var (section, icon) in _sections)
    {
        <button class="nav-link text-start d-flex align-items-center gap-2 @(section == ActiveSection ? "active" : "")"
                role="tab"
                aria-selected="@(section == ActiveSection)"
