                    <input type="password" class="form-control" id="newPw" @bind="_newPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label" for="confirmPw">Confirm New Password</label>
                    <input type="password" class="form-control" id="confirmPw" @bind="_confirmPassword" />
                </div>
                <button class="btn btn-warning" @onclick="ChangePasswordAsync">Update Password</button>
            </div>
        }
    </div>

    @* ── Two-Factor Authentication ── *@
    <div class="card mb-4">
        <div class="card-body d-flex justify-content-between align-items-center">
            <div>
                <h5 class="mb-1">Two-Factor Authentication</h5>
                <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            <div class="form-check form-switch m-0">
                <input type="checkbox" class="form-check-input" id="twoFactor"
                       @bind="_twoFactorEnabled" />
                <label class="visually-hidden" for="twoFactor">Toggle two-factor authentication</label>
            </div>
        </div>
    </div>

    @* ── Active Sessions ── *@
    <h5 class="mt-4 mb-2">Active Sessions</h5>
    @if (_lastPasswordChange is not null)
    {
        <p class="text-muted small mb-3">
            Last password change: @_lastPasswordChange.Value.ToString("g")
        </p>
    }

    <div class="table-responsive">
        <table class="table table-striped align-middle">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th class="text-end">Action</th>
                </tr>
            </thead>
            <tbody>
                @for (var i = 0; i < _sessions.Count; i++)
                {
                    var session = _sessions[i];
                    var isCurrent = i == 0;
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td class="text-end">
                            @if (isCurrent)
                            {
                                <span class="badge bg-info">Current</span>
                            }
                            else
                            {
                                <button class="btn btn-sm btn-outline-danger"
                                        @onclick="() => ConfirmRevoke(session)">
                                    Revoke
                                </button>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    @* ── Revoke Confirmation Dialog ── *@
    @if (_sessionToRevoke is not null)
    {
        <div class="modal d-block" tabindex="-1" style="background-color:rgba(0,0,0,0.5);"
             role="dialog" aria-modal="true">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">Confirm Session Revocation</h5>
                        <button type="button" class="btn-close" @onclick="CancelRevoke"
                                aria-label="Close"></button>
                    </div>
                    <div class="modal-body">
                        <p>
                            Are you sure you want to revoke the session on
                            <strong>@_sessionToRevoke.Device</strong> from
                            <strong>@_sessionToRevoke.Location</strong>?
                        </p>
                    </div>
                    <div class="modal-footer">
                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        <button class="btn btn-danger" @onclick="RevokeSessionAsync">Revoke Session</button>
                    </div>
                </div>
            </div>
        </div>
    }
}

@code {
    private bool _loading = true;
    private string? _message;
    private string _messageClass = "alert-success";
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();
    private bool _twoFactorEnabled;

    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";

    private ActiveSession? _sessionToRevoke;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = new List<ActiveSession>(settings.Sessions);
        _loading = false;
    }

    private async Task ChangePasswordAsync()
    {
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowError("New password cannot be empty.");
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            ShowError("New passwords do not match.");
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordExpanded = false;
        _lastPasswordChange = DateTime.UtcNow;
        ShowSuccess("Password updated successfully!");
    }

    private void ConfirmRevoke(ActiveSession session) => _sessionToRevoke = session;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task RevokeSessionAsync()
    {
        if (_sessionToRevoke is null) return;

        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _sessions.Remove(_sessionToRevoke);
        ShowSuccess($"Session on {_sessionToRevoke.Device} has been revoked.");
        _sessionToRevoke = null;
    }

    private void ShowSuccess(string msg)
    {
        _message = msg;
        _messageClass = "alert-success";
    }

    private void ShowError(string msg)
    {
        _message = msg;
        _messageClass = "alert-danger";
    }
}

