    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            @_message
            <button type="button" class="btn-close" @onclick="() => _message = null"></button>
        </div>
    }

    <div class="mb-4">
        <label class="form-label fw-semibold">Avatar</label>
        <div class="d-flex align-items-center gap-3">
            <img src="@_avatarUrl" alt="Avatar" class="rounded-circle"
                 style="width:72px;height:72px;object-fit:cover;border:2px solid var(--bs-border-color);" />
            <code class="text-muted small">@_avatarUrl</code>
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label fw-semibold" for="profile-name">Display Name</label>
        <input type="text" class="form-control" id="profile-name" @bind="_displayName" />
    </div>

    <div class="mb-3">
        <label class="form-label fw-semibold" for="profile-email">Email</label>
        <input type="email" class="form-control" id="profile-email" @bind="_email" />
    </div>

    <div class="mb-3">
        <label class="form-label fw-semibold" for="profile-bio">Bio</label>
        <textarea class="form-control" id="profile-bio" rows="4" @bind="_bio"></textarea>
