toolArgs.file_text:
@using sv_f71603591e574d85a2bc94f983845435.Services
@inject ISettingsService SettingsService

@if (_loading)
{
    <div class="d-flex justify-content-center p-5">
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading…</span>
        </div>
    </div>
}
else
{
    <h3 class="mb-4">Appearance Settings</h3>

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            @_message
            <button type="button" class="btn-close" @onclick="() => _message = null"></button>
        </div>
    }

    @* ── Theme ── *@
    <div class="card mb-4">
        <div class="card-header fw-semibold">Theme</div>
        <div class="card-body d-flex gap-4">
            @foreach (var theme in _themes)
            {
                var t = theme;
                <div class="form-check">
                    <input type="radio" class="form-check-input" name="theme"
                           id="@($"theme-{t}")" value="@t"
                           checked="@(_theme == t)"
                           @onchange="() => _theme = t" />
                    <label class="form-check-label" for="@($"theme-{t}")">@t</label>
                </div>
            }
        </div>
    </div>

    @* ── Font Size ── *@
    <div class="card mb-4">
        <div class="card-header fw-semibold">Font Size</div>
        <div class="card-body d-flex gap-4">
            @foreach (var size in _fontSizes)
            {
                var s = size;
                <div class="form-check">
                    <input type="radio" class="form-check-input" name="fontSize"
                           id="@($"fs-{s}")" value="@s"
                           checked="@(_fontSize == s)"
                           @onchange="() => _fontSize = s" />
                    <label class="form-check-label" for="@($"fs-{s}")">@s</label>
                </div>
            }
        </div>
    </div>

    @* ── Language ── *@
    <div class="card mb-4">
        <div class="card-header fw-semibold">Language</div>
        <div class="card-body">
            <select class="form-select" style="max-width:300px;" @bind="_language">
                <option value="en">English</option>
                <option value="es">Español</option>
                <option value="fr">Français</option>
                <option value="de">Deutsch</option>
                <option value="ja">日本語</option>
                <option value="zh">中文</option>
            </select>
        </div>
    </div>

    @* ── Compact Mode ── *@
    <div class="card mb-4">
        <div class="card-body">
            <div class="form-check form-switch">
                <input type="checkbox" class="form-check-input" id="compactMode"
                       @bind="_compactMode" />
                <label class="form-check-label" for="compactMode">Compact Mode</label>
            </div>
        </div>
    </div>

    @* ── Live Preview ── *@
    <div class="card mb-4">
        <div class="card-header fw-semibold">Preview</div>
        <div class="card-body" style="@PreviewContainerStyle">
            <h6 style="@PreviewFontStyle">Sample Heading</h6>
            <p style="@PreviewFontStyle" class="@(_compactMode ? "mb-1" : "mb-3")">
                This is a preview of how your content will look with the selected appearance settings.
            </p>
            <div class="d-flex gap-2 align-items-center">
                <button class="btn @PreviewButtonClass @(_compactMode ? "btn-sm" : "")" disabled>
                    Sample Button
                </button>
                <span class="badge @(_theme == "Dark" ? "bg-light text-dark" : "bg-dark")">Badge</span>
            </div>
        </div>
    </div>

    <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
}

@code {
    private bool _loading = true;
    private string? _message;
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];

    private string PreviewContainerStyle => _theme switch
    {
        "Dark" => "background-color:#1e1e1e;color:#d4d4d4;border-radius:0.375rem;",
        _ => "background-color:#ffffff;color:#212529;border-radius:0.375rem;"
    };

    private string PreviewFontStyle => _fontSize switch
    {
        "Small" => "font-size:0.85rem;",
        "Large" => "font-size:1.25rem;",
        _ => "font-size:1rem;"
    };

    private string PreviewButtonClass => _theme == "Dark" ? "btn-light" : "btn-primary";

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _message = "Appearance settings saved!";
    }
}

